# Add common defaults
for u in all_units:
    if "entrega_estimada" not in u:
        u["entrega_estimada"] = "2027"
    if "orientacion" not in u:
        obs = u.get("observaciones", "").lower()
        if "frente" in obs and "contrafrente" not in obs:
            u["orientacion"] = "Frente"
        elif "contrafrente" in obs:
            u["orientacion"] = "Contrafrente"
        else:
            u["orientacion"] = "Exterior"

print(f"Total units created: {len(all_units)}")
by_proy = {}
for u in all_units:
    p = u["proyecto"]
    if p not in by_proy:
        by_proy[p] = {"count": 0, "usd": 0, "ars": 0, "m2": 0}
    by_proy[p]["count"] += 1
    by_proy[p]["usd"] += u["precio_usd"]
    by_proy[p]["ars"] += u["precio_ars"]
    by_proy[p]["m2"] += u["m2_totales"]

for p, data in by_proy.items():
    print(f"{p}: {data['count']} unidades | USD {data['usd']:,.0f} | $ {data['ars']:,.0f} | {data['m2']:,.1f} m2")

total_usd = sum(u["precio_usd"] for u in all_units)
total_ars = sum(u["precio_ars"] for u in all_units)
total_m2 = sum(u["m2_totales"] for u in all_units)
print("-" * 50)
print(f"TOTAL GENERAL: {len(all_units)} unidades | USD {total_usd:,.0f} | $ {total_ars:,.0f} | {total_m2:,.1f} m2")

with open("stock_oficial_units_v3.json", "w", encoding="utf-8") as f:
    json.dump(all_units, f, ensure_ascii=False, indent=2)

print("Saved stock_oficial_units_v3.json successfully!")
